"use strict";
module.exports = /*#__PURE__*/JSON.parse('[{"id":"bahdanau-additive","name":"Bahdanau Attention","abbreviation":"Additive Attention","year":2014,"introducedBy":"Bahdanau, Cho & Bengio","introducedFor":"RNN encoder-decoder machine translation","paperTitle":"Neural Machine Translation by Jointly Learning to Align and Translate","paperUrl":"https://arxiv.org/abs/1409.0473","status":"Inactive","category":"Pre-Transformer","complexity":"O(n²)","summary":"The original attention mechanism: let a decoder look back at every encoder state and learn which ones matter for the current output word.","keyIdea":"Scores each encoder state with a small feed-forward network instead of a fixed alignment, then takes a weighted sum.","usedIn":["Early NMT systems","RNN/LSTM seq2seq models"]},{"id":"luong-multiplicative","name":"Luong Attention","abbreviation":"Multiplicative Attention","year":2015,"introducedBy":"Luong, Pham & Manning","introducedFor":"RNN-based neural machine translation","paperTitle":"Effective Approaches to Attention-based Neural Machine Translation","paperUrl":"https://arxiv.org/abs/1508.04025","status":"Inactive","category":"Pre-Transformer","complexity":"O(n²)","summary":"A simpler, faster alternative to Bahdanau attention that scores alignment with a dot product or small bilinear term instead of a full feed-forward network.","keyIdea":"Introduced global vs. local attention variants, and the dot-product scoring function that scaled dot-product attention later built on.","usedIn":["RNN/LSTM seq2seq models"]},{"id":"scaled-dot-product","name":"Scaled Dot-Product Attention","abbreviation":"SDPA","year":2017,"introducedBy":"Vaswani et al. (Google Brain / Google Research)","introducedFor":"The original Transformer architecture","paperTitle":"Attention Is All You Need","paperUrl":"https://arxiv.org/abs/1706.03762","status":"Active","category":"Foundational","complexity":"O(n²)","summary":"The core operation behind virtually every modern LLM: compare a query to every key with a dot product, scale, softmax, then take a weighted sum of values.","keyIdea":"softmax(QKᵀ / √dₖ)V — dividing by √dₖ keeps the dot products from growing too large and flattening the softmax gradient.","usedIn":["GPT family","Claude","Gemini","Llama","practically all Transformers"]},{"id":"multi-head","name":"Multi-Head Attention","abbreviation":"MHA","year":2017,"introducedBy":"Vaswani et al. (Google Brain / Google Research)","introducedFor":"The original Transformer architecture","paperTitle":"Attention Is All You Need","paperUrl":"https://arxiv.org/abs/1706.03762","status":"Active","category":"Foundational","complexity":"O(n²·d)","summary":"Runs several scaled dot-product attention operations in parallel, each with its own learned projections, so different heads can specialize in different relationships.","keyIdea":"Split the model dimension across h independent heads, attend separately, then concatenate and project back — giving the model several \'representation subspaces\' at once.","usedIn":["Original Transformer","BERT","early GPT models"]},{"id":"self-attention","name":"Self-Attention","abbreviation":null,"year":2017,"introducedBy":"Vaswani et al. (Google Brain / Google Research)","introducedFor":"Letting a sequence attend to itself instead of a separate source sequence","paperTitle":"Attention Is All You Need","paperUrl":"https://arxiv.org/abs/1706.03762","status":"Active","category":"Foundational","complexity":"O(n²)","summary":"Queries, keys, and values all come from the same sequence, so every token can directly weigh every other token in one step — no recurrence needed.","keyIdea":"Replacing recurrence with direct token-to-token comparison is what let Transformers parallelize training and capture long-range dependencies so much better than RNNs.","usedIn":["Every Transformer-based LLM"]},{"id":"cross-attention","name":"Cross-Attention","abbreviation":"Encoder-Decoder Attention","year":2017,"introducedBy":"Vaswani et al. (Google Brain / Google Research)","introducedFor":"Letting a decoder attend to a separate encoder\'s output","paperTitle":"Attention Is All You Need","paperUrl":"https://arxiv.org/abs/1706.03762","status":"Active","category":"Foundational","complexity":"O(n·m)","summary":"Queries come from one sequence (e.g. the decoder) while keys and values come from another (e.g. the encoder) — the mechanism that lets translation and multimodal models fuse two inputs.","keyIdea":"Generalizes attention to two different sequences instead of one, which is also how text-to-image and vision-language models fuse modalities today.","usedIn":["Encoder-decoder Transformers (T5, original translation models)","vision-language models","Stable Diffusion\'s text conditioning"]},{"id":"causal-masked","name":"Causal (Masked) Self-Attention","abbreviation":null,"year":2018,"introducedBy":"Vaswani et al.; popularized for language modeling by Radford et al. (OpenAI)","introducedFor":"Autoregressive, decoder-only language modeling (GPT)","paperTitle":"Improving Language Understanding by Generative Pre-Training","paperUrl":"https://cdn.openai.com/research-covers/language-unsupervised/language_understanding_paper.pdf","status":"Active","category":"Foundational","complexity":"O(n²)","summary":"Self-attention with a triangular mask so each token can only see itself and earlier tokens — essential for models that generate text one token at a time.","keyIdea":"Masking future positions with -∞ before softmax makes training on a whole sequence at once equivalent to next-token prediction, without leaking the answer.","usedIn":["GPT family","Claude","Gemini","Llama","practically all decoder-only LLMs"]},{"id":"sparse-transformer","name":"Sparse Transformer","abbreviation":"Factorized Attention","year":2019,"introducedBy":"Child, Gray, Radford & Sutskever (OpenAI)","introducedFor":"Modeling very long sequences (text, images, audio) affordably","paperTitle":"Generating Long Sequences with Sparse Transformers","paperUrl":"https://arxiv.org/abs/1904.10509","status":"Inactive","category":"Efficiency","complexity":"O(n√n)","summary":"Instead of attending to every previous token, each token attends to a structured subset (e.g. a local window plus a strided pattern) to cut cost on long inputs.","keyIdea":"Factorizing full attention into a small number of sparse patterns whose union still lets information flow across the whole sequence in a few layers.","usedIn":["Early long-sequence and image-generation Transformers"]},{"id":"multi-query-mqa","name":"Multi-Query Attention","abbreviation":"MQA","year":2019,"introducedBy":"Noam Shazeer (Google)","introducedFor":"Faster autoregressive decoding by shrinking the KV cache","paperTitle":"Fast Transformer Decoding: One Write-Head is All You Need","paperUrl":"https://arxiv.org/abs/1911.02150","status":"Active","category":"Inference Optimization","complexity":"O(n²), smaller memory constant","summary":"All query heads share a single key/value head instead of each having its own — a big memory win at some cost to quality.","keyIdea":"The real bottleneck in autoregressive decoding is memory bandwidth for re-reading the KV cache, not compute — so shrinking K/V storage speeds up generation a lot.","usedIn":["Falcon","PaLM","StarCoder/SantaCoder"]},{"id":"reformer-lsh","name":"Reformer (LSH Attention)","abbreviation":"LSH Attention","year":2020,"introducedBy":"Kitaev, Kaiser & Levskaya (Google)","introducedFor":"Making very long-context Transformers memory-efficient","paperTitle":"Reformer: The Efficient Transformer","paperUrl":"https://arxiv.org/abs/2001.04451","status":"Inactive","category":"Efficiency","complexity":"O(n log n)","summary":"Uses locality-sensitive hashing to bucket similar queries and keys together, so each token only attends within its bucket instead of the whole sequence.","keyIdea":"Tokens likely to have high attention scores tend to hash to the same bucket, so LSH turns full attention into an approximate nearest-neighbor search.","usedIn":["Research long-context models (limited production adoption)"]},{"id":"longformer","name":"Longformer Attention","abbreviation":"Sliding Window + Global","year":2020,"introducedBy":"Beltagy, Peters & Cohan (Allen Institute for AI)","introducedFor":"Long-document NLP tasks (summarization, QA)","paperTitle":"Longformer: The Long-Document Transformer","paperUrl":"https://arxiv.org/abs/2004.05150","status":"Inactive","category":"Long-Context","complexity":"O(n)","summary":"Combines a local sliding window (every token attends to nearby tokens) with a few \'global\' tokens that attend to and are attended by everything.","keyIdea":"Local context covers most linguistic structure cheaply, while a handful of global tokens (like [CLS]) still let information travel across the whole document.","usedIn":["Long-document BERT-style models"]},{"id":"bigbird","name":"BigBird Attention","abbreviation":null,"year":2020,"introducedBy":"Zaheer et al. (Google Research)","introducedFor":"Longer sequences for NLP and genomics","paperTitle":"Big Bird: Transformers for Longer Sequences","paperUrl":"https://arxiv.org/abs/2007.14062","status":"Inactive","category":"Long-Context","complexity":"O(n)","summary":"Blends random attention, a local window, and global tokens — proven to still be a universal sequence approximator despite being sparse.","keyIdea":"Random attention edges act like random graph shortcuts, keeping the effective \'distance\' between any two tokens small even though most pairs never attend directly.","usedIn":["Long-document and genomic sequence models"]},{"id":"linformer","name":"Linformer","abbreviation":"Low-Rank Attention","year":2020,"introducedBy":"Wang, Li, Khabsa, Fang & Ma (Facebook AI)","introducedFor":"Linear-time self-attention","paperTitle":"Linformer: Self-Attention with Linear Complexity","paperUrl":"https://arxiv.org/abs/2006.04768","status":"Inactive","category":"Efficiency","complexity":"O(n)","summary":"Projects the keys and values down to a fixed, smaller size before attending, based on the observation that attention matrices are often approximately low-rank.","keyIdea":"If attention is approximately low-rank, you can compress the sequence dimension of K and V with a learned linear projection with little accuracy loss.","usedIn":["Research efficiency baselines"]},{"id":"performer","name":"Performer","abbreviation":"FAVOR+","year":2020,"introducedBy":"Choromanski et al. (Google)","introducedFor":"Unbiased, linear-time approximation of softmax attention","paperTitle":"Rethinking Attention with Performers","paperUrl":"https://arxiv.org/abs/2009.14794","status":"Inactive","category":"Efficiency","complexity":"O(n)","summary":"Approximates the softmax attention kernel using random feature maps, avoiding ever materializing the full n×n attention matrix.","keyIdea":"FAVOR+ (Fast Attention Via positive Orthogonal Random features) gives a provably unbiased estimate of regular softmax attention while running in linear time.","usedIn":["Research efficiency baselines"]},{"id":"flashattention-1","name":"FlashAttention","abbreviation":"FA1","year":2022,"introducedBy":"Dao, Fu, Ermon, Rudra & Ré (Stanford)","introducedFor":"Exact attention without the memory/speed penalty of materializing the full attention matrix","paperTitle":"FlashAttention: Fast and Memory-Efficient Exact Attention with IO-Awareness","paperUrl":"https://arxiv.org/abs/2205.14135","status":"Inactive","category":"Systems / Implementation","complexity":"O(n²) compute, O(n) memory","summary":"Not a new attention pattern — an IO-aware algorithm that computes the exact same attention output while avoiding slow reads/writes to GPU high-bandwidth memory.","keyIdea":"Tiles the computation into blocks that fit in fast on-chip SRAM, using online softmax so the full n×n score matrix never has to be written to HBM.","usedIn":["Superseded by FlashAttention-2/3/4 in current training stacks"]},{"id":"flashattention-2","name":"FlashAttention-2","abbreviation":"FA2","year":2023,"introducedBy":"Tri Dao (Princeton / Together AI)","introducedFor":"Better GPU parallelism and work partitioning than FlashAttention","paperTitle":"FlashAttention-2: Faster Attention with Better Parallelism and Work Partitioning","paperUrl":"https://arxiv.org/abs/2307.08691","status":"Active","category":"Systems / Implementation","complexity":"O(n²) compute, O(n) memory","summary":"Reworks FlashAttention\'s parallelization to cut non-matmul operations and better use GPU warps, roughly doubling throughput.","keyIdea":"Better work partitioning across thread blocks and warps pushes GPU utilization much closer to what optimized matrix multiplication achieves.","usedIn":["Standard on Ampere-class and older GPUs (A100 and earlier) across most training/inference stacks"]},{"id":"flashattention-3","name":"FlashAttention-3","abbreviation":"FA3","year":2024,"introducedBy":"Shah, Bikshandi, Zhang, Thakkar, Ramani & Dao (Colfax Research, Meta, NVIDIA, Together AI, Princeton)","introducedFor":"Exploiting Hopper-generation GPU features (H100) that FlashAttention-2 left on the table","paperTitle":"FlashAttention-3: Fast and Accurate Attention with Asynchrony and Low-precision","paperUrl":"https://arxiv.org/abs/2407.08608","status":"Active","category":"Systems / Implementation","complexity":"O(n²) compute, O(n) memory","summary":"Overlaps computation and data movement using Hopper\'s asynchronous Tensor Cores, and adds a low-precision (FP8) mode.","keyIdea":"Warp-specialization plus interleaving matmul and softmax steps pushed H100 utilization from ~35% to ~75% of theoretical peak.","usedIn":["Standard on Hopper-class GPUs (H100/H200)"]},{"id":"flashattention-4","name":"FlashAttention-4","abbreviation":"FA4","year":2026,"introducedBy":"Tri Dao and collaborators (Princeton, Together AI, Meta, NVIDIA, Colfax Research)","introducedFor":"Rearchitecting attention for NVIDIA Blackwell GPUs, where non-matmul units became the new bottleneck","paperTitle":"FlashAttention-4: Algorithm and Kernel Pipelining Co-Design for Asymmetric Hardware Scaling","paperUrl":"https://arxiv.org/abs/2603.05451","status":"Active","category":"Systems / Implementation","complexity":"O(n²) compute, O(n) memory","summary":"A ground-up redesign for Blackwell GPUs (B200/B300) that software-emulates exponentials on FMA units and skips unnecessary softmax rescaling to work around shifted hardware bottlenecks.","keyIdea":"As matmul throughput on Blackwell outpaced shared-memory bandwidth and exponential units, FA4 co-designs the algorithm around those new bottlenecks instead of the old ones — reaching attention speeds close to raw matmul.","usedIn":["Blackwell-generation inference/training stacks (B200/B300)"]},{"id":"grouped-query-gqa","name":"Grouped-Query Attention","abbreviation":"GQA","year":2023,"introducedBy":"Ainslie, Lee-Thorp, de Jong, Zemlyanskiy, Lebrón & Sanghai (Google Research)","introducedFor":"Interpolating between MHA\'s quality and MQA\'s speed","paperTitle":"GQA: Training Generalized Multi-Query Transformer Models from Multi-Head Checkpoints","paperUrl":"https://arxiv.org/abs/2305.13245","status":"Active","category":"Inference Optimization","complexity":"O(n²), tunable memory constant","summary":"Query heads are split into groups, and each group shares one key/value head — g=1 recovers MQA, g=h recovers full MHA.","keyIdea":"A tunable dial between MQA\'s efficiency and MHA\'s quality; existing MHA checkpoints can be \'uptrained\' into GQA with a small fraction of extra training.","usedIn":["Llama 3/4","Mistral","Gemma","Qwen3","the de facto default for most current open-weight models"]},{"id":"sliding-window","name":"Sliding Window Attention","abbreviation":null,"year":2023,"introducedBy":"Popularized in production by Mistral AI","introducedFor":"Bounding attention cost per token regardless of total context length","paperTitle":"Mistral 7B","paperUrl":"https://arxiv.org/abs/2310.06825","status":"Active","category":"Long-Context","complexity":"O(n·w)","summary":"Each token only attends to the most recent w tokens instead of the entire sequence, capping per-token attention cost at a fixed window size.","keyIdea":"Stacked across layers, a fixed window still lets information propagate across a much larger effective receptive field, similar in spirit to convolutional receptive fields.","usedIn":["Mistral 7B and later Mistral models"]},{"id":"attention-sinks-streamingllm","name":"Attention Sinks (StreamingLLM)","abbreviation":null,"year":2023,"introducedBy":"Xiao, Tian, Chen, Han & Lewis (MIT, Meta AI, Carnegie Mellon)","introducedFor":"Letting sliding-window LLMs handle effectively infinite streaming text without fine-tuning","paperTitle":"Efficient Streaming Language Models with Attention Sinks","paperUrl":"https://arxiv.org/abs/2309.17453","status":"Active","category":"Long-Context","complexity":"O(n·w)","summary":"Discovered that models dump disproportionate attention onto the very first few tokens as a stabilizing \'sink\' — keeping just those tokens plus a sliding window recovers full-attention-quality streaming.","keyIdea":"Softmax always has to sum to 1, so when nothing is relevant the model needs somewhere to dump the leftover probability mass — the first tokens become that dumping ground.","usedIn":["Streaming/long-conversation inference setups","influenced KV-cache eviction strategies broadly"]},{"id":"ring-attention","name":"Ring Attention","abbreviation":null,"year":2023,"introducedBy":"Liu, Zaharia & Abbeel (UC Berkeley)","introducedFor":"Training/inference on near-infinite context by distributing sequences across many devices","paperTitle":"Ring Attention with Blockwise Transformers for Near-Infinite Context","paperUrl":"https://arxiv.org/abs/2310.01889","status":"Active","category":"Long-Context","complexity":"O(n²/devices)","summary":"Splits a very long sequence into blocks across a ring of devices, overlapping the communication of key/value blocks with the attention computation itself.","keyIdea":"Because the communication is fully hidden behind computation, effective context length scales with the number of devices, with no extra communication overhead.","usedIn":["Very-long-context training infrastructure (million-token-scale)"]},{"id":"multi-head-latent-mla","name":"Multi-Head Latent Attention","abbreviation":"MLA","year":2024,"introducedBy":"DeepSeek-AI","introducedFor":"Shrinking the KV cache far more aggressively than GQA without MQA\'s quality loss","paperTitle":"DeepSeek-V2: A Strong, Economical, and Efficient Mixture-of-Experts Language Model","paperUrl":"https://arxiv.org/abs/2405.04434","status":"Active","category":"Inference Optimization","complexity":"O(n²), low-rank-compressed memory","summary":"Compresses keys and values into a small shared latent vector (like a learned low-rank projection) instead of storing separate K/V per head or group.","keyIdea":"Caching a compressed latent representation — and reconstructing per-head K/V from it on the fly — gets GQA-or-better quality at closer to MQA-level cache size.","usedIn":["DeepSeek-V2","DeepSeek-V3","DeepSeek-V3.2"]},{"id":"differential-attention","name":"Differential Attention","abbreviation":"Diff Transformer","year":2024,"introducedBy":"Ye, Dong, Xia, Sun, Zhu, Huang & Wei (Microsoft Research, Tsinghua University)","introducedFor":"Reducing \'attention noise\' — wasted attention mass on irrelevant context","paperTitle":"Differential Transformer","paperUrl":"https://arxiv.org/abs/2410.05258","status":"Active","category":"Emerging Research","complexity":"O(n²), roughly 2× the projections of standard attention","summary":"Computes attention as the difference between two separate softmax attention maps, so common-mode noise cancels out and only genuine signal remains.","keyIdea":"Two attention maps, subtracted with a learned weight λ, naturally suppress the noisy attention that plain softmax struggles to fully zero out, sharpening focus on truly relevant tokens.","usedIn":["Research models; cited as a building block in several 2025 efficient-attention follow-ups"]},{"id":"native-sparse-attention-nsa","name":"Native Sparse Attention","abbreviation":"NSA","year":2025,"introducedBy":"Yuan, Gao, Dai et al. (DeepSeek-AI, Peking University)","introducedFor":"Hardware-aligned sparse attention that can be trained end-to-end, not just applied at inference","paperTitle":"Native Sparse Attention: Hardware-Aligned and Natively Trainable Sparse Attention","paperUrl":"https://arxiv.org/abs/2502.11089","status":"Active","category":"Efficiency","complexity":"O(n) — sparse, hardware-aligned","summary":"Combines three parallel branches — compressed coarse attention, selected important blocks, and a local sliding window — tuned to run efficiently on real GPU hardware.","keyIdea":"Unlike most sparse-attention methods that are bolted on after pretraining, NSA is designed to be trained from scratch, matching or beating full attention quality at a fraction of the cost on 64K+ token sequences.","usedIn":["DeepSeek research models; referenced as related work in DeepSeek-V3.2"]}]');

